const nextMonths = () => { const now = new Date(); const out = []; for (let i = 1; i <= 6; i++) { const m = (now.getMonth() + i) % 12; out.push({ l: MON[m], idx: m }); } return out; };
const monthItems = (dest) => { if (!weatherData[dest]) return nextMonths(); const items = nextMonths().map((m) => ({ ...m, ...monthWeather(dest, m.idx) })); const best = items.filter((m) => m.rain < 120).sort((a, b) => a.rain - b.rain).slice(0, 2); best.forEach((b) => { b.best = true; }); return items; };

